package cn.xiaoyanjiu.ff14chat;
import java.net.*;import java.nio.*;import java.io.*;import java.security.*;import java.util.*;
final class UdpVideoTransport implements AutoCloseable {
 final DatagramSocket socket;final byte[] key;final UdpVideoProtocol.Assembler assembler;final UdpVideoProtocol.Replay replay=new UdpVideoProtocol.Replay();volatile boolean live=true;long sequence;final byte[] clientChallenge=new byte[16];byte[] challenge;long lastFrame,lastAck;boolean paused;
 UdpVideoTransport(InetSocketAddress address,byte[] secret,UdpVideoProtocol.Sink sink)throws Exception{key=secret.clone();if(key.length!=32)throw new IOException("UDP密钥无效");new SecureRandom().nextBytes(clientChallenge);socket=new DatagramSocket();socket.setReceiveBufferSize(2097152);socket.setSendBufferSize(65536);socket.connect(address);socket.setSoTimeout(40);assembler=new UdpVideoProtocol.Assembler(new UdpVideoProtocol.Sink(){public void frame(byte[] bytes){lastFrame=System.nanoTime()/1000000;sink.frame(bytes);}public void loss(){sink.loss();}});}
 void send(int type,byte[] payload)throws Exception{byte[] b=UdpVideoProtocol.seal(key,false,type,0,0,0,0,++sequence,0,payload);socket.send(new DatagramPacket(b,b.length));}
 void run()throws Exception{long began=System.nanoTime()/1000000,lastHello=0,lastPing=0;lastFrame=began;byte[] storage=new byte[1201];while(live){long now=System.nanoTime()/1000000;if(challenge==null&&now-lastHello>=500){send(1,clientChallenge);lastHello=now;}if(challenge!=null&&now-lastPing>=400){byte[] p=ByteBuffer.allocate(32).put(challenge).putInt((int)assembler.completed).putInt((int)assembler.lost).putLong(0).array();send(6,p);lastPing=now;}if(challenge==null&&now-began>5000)throw new IOException("UDP连接超时：请映射或放行UDP端口，或选择TCP兼容模式");if(challenge!=null&&now-lastAck>3000)throw new IOException("UDP心跳中断，正在重新连接");if(challenge!=null&&now-lastFrame>6000)throw new IOException("UDP视频帧超时，请检查编码器或降低码率");try{DatagramPacket received=new DatagramPacket(storage,storage.length);socket.receive(received);byte[] b=Arrays.copyOf(storage,received.getLength());UdpVideoProtocol.Packet p;try{p=UdpVideoProtocol.open(key,true,b);}catch(GeneralSecurityException invalid){continue;}if(!replay.accept(p.sequence))continue;if(p.type==2&&p.flags==0&&p.bytes.length==32&&MessageDigest.isEqual(clientChallenge,Arrays.copyOf(p.bytes,16))){challenge=Arrays.copyOfRange(p.bytes,16,32);lastAck=now;lastPing=0;}else if(p.type==2&&p.flags==1&&p.bytes.length==16&&challenge!=null&&MessageDigest.isEqual(challenge,p.bytes)){lastAck=now;}else if(challenge!=null){assembler.accept(p,now);}}catch(SocketTimeoutException timeout){assembler.drain(now);}}}
 public void close(){live=false;socket.close();Arrays.fill(key,(byte)0);}
}
